INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Verwendung von abgeschirmten Kabeln (STP) in Umgebungen mit hohen elektromagnetischen Störungen sinnvoll?', 2, '[{"text": "Ja", "correct": true, "because": "Abschirmung reduziert Störungen"}, {"text": "Nein", "correct": false, "because": "STP ist dafür geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Cat5e-Kabel für ein 10-Gbit/s-Netzwerk über kurze Distanzen verwendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Bis ca. 45 m möglich"}, {"text": "Nein", "correct": false, "because": "Cat5e unterstützt 10 Gbit/s kurzfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Kabel bei der Netzwerkeinrichtung immer nach T568B verdrillt werden?', 2, '[{"text": "Nein", "correct": true, "because": "T568A ist ebenfalls gültig"}, {"text": "Ja", "correct": false, "because": "Beide Standards sind erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Glasfaserkabel für die Verkabelung in einem kleinen Büro mit kurzen Distanzen überdimensioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Twisted-Pair reicht für kurze Distanzen"}, {"text": "Nein", "correct": false, "because": "Glasfaser ist teurer und komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Patchkabel bei der Netzwerkeinrichtung für lange Strecken verwendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Patchkabel sind für kurze Verbindungen gedacht"}, {"text": "Ja", "correct": false, "because": "Längere Distanzen brauchen Installationskabel"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Kabeltyp ist für eine Verkabelung über 100 Meter in einem Gebäude am besten geeignet?', 2, '[{"text": "Glasfaserkabel", "correct": true, "because": "Glasfaser überwindet 100-m-Limit"}, {"text": "Cat6", "correct": false, "because": "Begrenzt auf 100 m"}, {"text": "Koaxialkabel", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche maximale Übertragungsrate unterstützt ein Cat6a-Kabel über 100 Meter?', 3, '[{"text": "10 Gbit/s", "correct": true, "because": "Cat6a ist dafür ausgelegt"}, {"text": "1 Gbit/s", "correct": false, "because": "Cat5e reicht dafür"}, {"text": "100 Mbit/s", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Stecker wird für die Verkabelung mit Twisted-Pair-Kabeln in einem Gigabit-Netzwerk verwendet?', 2, '[{"text": "RJ45", "correct": true, "because": "Standard für Ethernet"}, {"text": "SC", "correct": false, "because": "Für Glasfaser"}, {"text": "BNC", "correct": false, "because": "Für Koaxial"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kabel sollte für eine Verkabelung in einem Rechenzentrum mit hoher Bandbreite gewählt werden?', 2, '[{"text": "Glasfaser", "correct": true, "because": "Hohe Bandbreite und Reichweite"}, {"text": "Cat5e", "correct": false, "because": "Begrenzt auf 1 Gbit/s"}, {"text": "Cat6", "correct": false, "because": "Weniger geeignet als Glasfaser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard wird bevorzugt, um sicherzustellen, dass Kabel in einem Netzwerk korrekt verdrillt sind?', 2, '[{"text": "T568B", "correct": true, "because": "Weit verbreitet und kompatibel"}, {"text": "T568A", "correct": false, "because": "Auch gültig, aber seltener"}, {"text": "IEEE 802.3", "correct": false, "because": "Für Ethernet, nicht Verdrillung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kabeltypen sind für die Netzwerkeinrichtung geeignet?', 4, '[{"text": "Cat6a", "correct": true, "because": "Für 10 Gbit/s"}, {"text": "Glasfaser", "correct": true, "because": "Für hohe Bandbreiten"}, {"text": "Cat5e", "correct": true, "because": "Für Gigabit-Ethernet"}, {"text": "USB-Kabel", "correct": false, "because": "Nicht für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sollten bei der Auswahl eines Kabels für die Verkabelung berücksichtigt werden?', 3, '[{"text": "Entfernung", "correct": true, "because": "Beeinflusst Kabeltyp"}, {"text": "Bandbreitenbedarf", "correct": true, "because": "z. B. 1 Gbit/s oder 10 Gbit/s"}, {"text": "Störungsanfälligkeit", "correct": true, "because": "Abschirmung nötig"}, {"text": "Farbe", "correct": false, "because": "Nur organisatorisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Verwendung von Cat7-Kabeln bei der Netzwerkeinrichtung?', 4, '[{"text": "Hohe Bandbreite (10 Gbit/s)", "correct": true, "because": "Bis 100 m"}, {"text": "Bessere Abschirmung", "correct": true, "because": "Reduziert Störungen"}, {"text": "Zukunftssicherheit", "correct": true, "because": "Für höhere Geschwindigkeiten"}, {"text": "Geringere Kosten", "correct": false, "because": "Teurer als Cat6"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards sind bei der Verkabelung für Gigabit-Ethernet relevant?', 3, '[{"text": "T568B", "correct": true, "because": "Pinbelegung"}, {"text": "T568A", "correct": true, "because": "Alternative Pinbelegung"}, {"text": "Cat5e", "correct": true, "because": "Mindestanforderung"}, {"text": "WPA3", "correct": false, "because": "Für WLAN-Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge sind für die Verkabelung bei der Netzwerkeinrichtung hilfreich?', 3, '[{"text": "Kabeltester", "correct": true, "because": "Prüft Verbindungen"}, {"text": "Crimper", "correct": true, "because": "Für RJ45-Stecker"}, {"text": "Punch-Down-Tool", "correct": true, "because": "Für Anschlussdosen"}, {"text": "Schraubendreher", "correct": false, "because": "Weniger spezifisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Cat6a ist für 10 Gbit/s über 100 Meter geeignet. b) Glasfaserkabel sind für kurze Distanzen ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cat6a ja, Glasfaser auch für kurz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) T568B ist der bevorzugte Standard für Netzwerkverkabelung. b) Cat5e unterstützt keine Gigabit-Geschwindigkeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "T568B ja, Cat5e unterstützt Gigabit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Glasfaserkabel bieten Immunität gegen elektromagnetische Störungen. b) Patchkabel sind für Verkabelungen über 100 Meter ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Glasfaser ja, Patchkabel nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) RJ45-Stecker sind für Twisted-Pair-Kabel Standard. b) Cat7 unterstützt bis zu 10 Gbit/s über 100 Meter.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "RJ45 ja, Cat7 bis 10 Gbit/s"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Abgeschirmte Kabel (STP) sind in störungsanfälligen Umgebungen vorteilhaft. b) Koaxialkabel sind der aktuelle Standard für Gigabit-Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "STP ja, Koaxial veraltet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

